Commune.command:
/**
 * Daggerheart Commune Macro
 * V12 Compatible - Fixed Dice Display & Inherited Colors
 */

const actor = canvas.tokens.controlled[0]?.actor || game.user.character;

if (!actor) {
    ui.notifications.warn("Please select a token or assign a character.");
} else {
    // 1. Determine Spellcast Trait from Subclass
    const subclassItem = actor.items.find(i => i.type === "subclass");
    const traitKey = subclassItem?.system?.spellcastingTrait || "instinct";
    const spellcastValue = actor.system.traits?.[traitKey]?.value ?? 1;

    // 2. Roll the dice
    const rollFormula = `${spellcastValue}d6`;
    const r = new Roll(rollFormula);
    await r.evaluate();

    // 3. Extract unique results for the effect check
    const results = [...new Set(r.dice[0].results.map(res => res.result))];

    // 4. Map the effect list and filter by what was rolled
    const effectList = [
        { 
            check: results.some(n => n >= 1 && n <= 3), 
            text: "<li style='margin-bottom: 12px; line-height: 1.4;'><strong>1-3:</strong> You taste a flavor, smell a scent, or feel a sensation relevant to the answer.</li>" 
        },
        { 
            check: results.some(n => n >= 4 && n <= 5), 
            text: "<li style='margin-bottom: 12px; line-height: 1.4;'><strong>4-5:</strong> You hear sounds or see a vision relevant to the answer.</li>" 
        },
        { 
            check: results.includes(6), 
            text: "<li style='line-height: 1.4;'><strong>6:</strong> You psychically experience a scene relevant to the answer as if you were there.</li>" 
        }
    ];

    const activeEffects = effectList.filter(e => e.check).map(e => e.text).join("");

    // 5. Build HTML
    let content = `
        <div class="dice-roll">
            <div class="dice-result">
                <div style="padding: 8px; border-radius: 4px; border: 1px solid currentColor; margin-bottom: 12px; text-align: center; opacity: 0.9;">
                    <h2 style="border: none; margin: 0; text-transform: uppercase; font-size: 1.3em; letter-spacing: 1px; color: inherit;">Commune</h2>
                    <div style="font-size: 0.85em; margin-top: 2px; color: inherit; opacity: 0.8;">Trait: <strong>${traitKey.charAt(0).toUpperCase() + traitKey.slice(1)}</strong></div>
                </div>
                <div class="dice-tooltip" style="display: block;">
                    <ol class="dice-rolls" style="display: flex; flex-wrap: wrap; gap: 4px; list-style: none; padding: 0;">
                        ${r.dice[0].results.map(res => `<li class="roll die d6" style="margin: 0;">${res.result}</li>`).join("")}
                    </ol>
                </div>
            </div>
        </div>
        <div style="margin-top: 12px; border-top: 1px solid currentColor; padding-top: 10px; opacity: 0.9;">
            <p style="font-size: 0.9em; margin-bottom: 10px;"><em>Choose one rolled result:</em></p>
            <ul style="list-style: none; padding-left: 0; margin: 0;">
                ${activeEffects}
            </ul>
        </div>
    `;

    await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: content,
        rolls: [r],
        style: CONST.CHAT_MESSAGE_STYLES.ROLL
    });
}

Eyestalks.command:
/**
 * Eyestalks Action Macro (Daggerheart - Standard Button Fix)
 * Rolls a d10 and executes the specific action ID found in the feature.
 */

const token = canvas.tokens.controlled[0];
const actor = token?.actor;

if (!actor) {
  ui.notifications.warn("Please select a Gobstalker token.");
} else {
  const roll = await new Roll("1d10").evaluate({async: true});
  const result = roll.total;

  // Find the item starting with the roll number
  const item = actor.items.find(i => i.name.trim().startsWith(result.toString()));

  let content = `<div><p><strong>Eyestalks Roll:</strong> ${result}</p>`;

  if (item) {
    // Get the first action ID from the item's system data
    const actionId = Object.keys(item.system.actions || {})[0];

    if (actionId) {
      // Using standard Foundry 'chat-button' class for consistent look
      content += `
        <button class="execute-dh-action" 
                data-actor-id="${actor.id}" 
                data-item-id="${item.id}" 
                data-action-id="${actionId}">
          Activate ${item.name}
        </button>`;
    } else {
      // Fallback for items like 'Doom' that have no programmed action
      content += `
        <button class="show-dh-description" 
                data-actor-id="${actor.id}" 
                data-item-id="${item.id}">
          Show ${item.name}
        </button>`;
    }
  } else {
    content += `<p style="color: red;">Feature ${result} not found.</p>`;
  }

  content += `</div>`;

  await roll.toMessage({
    flavor: "Gobstalker Eye Beam",
    content: content + (await roll.render())
  });
}

// listener for programmed actions (Damage, Effects, etc.)
$(document).off("click", ".execute-dh-action").on("click", ".execute-dh-action", async (event) => {
  event.preventDefault();
  const { actorId, itemId, actionId } = event.currentTarget.dataset;
  const actor = game.actors.get(actorId) || canvas.tokens.get(actorId)?.actor;
  const item = actor?.items.get(itemId);

  if (item && actionId) {
    // This is the specific method used by the Daggerheart system to run action logic
    await item.executeAction(actionId);
  }
});

// listener for text-only features
$(document).off("click", ".show-dh-description").on("click", ".show-dh-description", async (event) => {
  event.preventDefault();
  const { actorId, itemId } = event.currentTarget.dataset;
  const actor = game.actors.get(actorId) || canvas.tokens.get(actorId)?.actor;
  const item = actor?.items.get(itemId);

  if (item) {
    const chatData = {
      user: game.user.id,
      speaker: ChatMessage.getSpeaker({ actor: actor }),
      content: `<h3>${item.name}</h3>${item.system.description}`
    };
    ChatMessage.create(chatData);
  }
});
